    from collections import deque

class Node:
    def __init__(self, x):
        self.data = x
        self.left = None
        self.right = None

def findSpiral(root):
    res = []
    if not root:
        return res

    dq = deque()
    dq.append(root)

    reverse = True

    while dq:
        n = len(dq)

        while n > 0:
            # Push right first if reverse is true
            if reverse:
                curr = dq.pop()
                res.append(curr.data)

                if curr.right:
                    dq.appendleft(curr.right)
                if curr.left:
                    dq.appendleft(curr.left)
            # Else push left first
            else:
                curr = dq.popleft()
                res.append(curr.data)

                if curr.left:
                    dq.append(curr.left)
                if curr.right:
                    dq.append(curr.right)

            n -= 1

        reverse = not reverse

    return res

