    class Node {
    constructor(x) {
        this.data = x;
        this.left = null;
        this.right = null;
    }
}

function findSpiral(root) {
    let res = [];
    if (!root) return res;

    let dq = [];
    dq.push(root);

    let reverse = true;

    while (dq.length > 0) {
        let n = dq.length;

        while (n-- > 0) {
            // Push right first if reverse is true
            if (reverse) {
                let curr = dq.pop();
                res.push(curr.data);

                if (curr.right) dq.unshift(curr.right);
                if (curr.left) dq.unshift(curr.left);
            }
            // Else push left first
            else {
                let curr = dq.shift();
                res.push(curr.data);

                if (curr.left) dq.push(curr.left);
                if (curr.right) dq.push(curr.right);
            }
        }
        reverse = !reverse;
    }
    return res;
}

